// a level polyline along +X: n segments, each heading within 90° of +X; segment lengths add what the rounded corners cut off
const R = corner_radius, n = clamp(floor(path_length / max(6, 2.4 * R + 2)), 1, 8);
const heading = [0], turn = [];
for (let k = 1; k < n; k++) {
  const h = heading[k - 1], s = rand(k, seed, 1) < 0.5 ? -1 : 1, d = 50 + 40 * rand(k, seed, 2);
  const h2 = abs(h + s * d) <= 90 ? h + s * d : h - s * d;
  heading.push(h2); turn.push(h2 - h);
}
let cut = 0;
for (const t of turn) { const a = radians(abs(t)); cut += 2 * R * Math.tan(a / 2) - R * a; }
const w = []; let wsum = 0;
for (let k = 0; k < n; k++) { w.push(0.9 + 0.2 * rand(k, seed, 3)); wsum += w[k]; }
let p = [0, 0, 0];
const pts = [addpoint(0, p)];
for (let k = 0; k < n; k++) {
  const L = (path_length + cut) * w[k] / wsum, a = radians(heading[k]);
  p = [p[0] + L * cos(a), 0, p[2] - L * sin(a)];
  pts.push(addpoint(0, p));
}
for (let k = 0; k <= n; k++) setpointattrib(0, 'turn', pts[k], k > 0 && k < n ? sign(turn[k - 1]) : 0);
addprim(0, 'polyline', pts);

// pipes stacked in rows on the arms, centred below the knee rail; a further column outward when the rows do not fit
const r = pipe_radius, gap = max(0.03, 0.5 * r), per = 2 * r + gap;
const fit = max(1, floor((0.8 * rail_height - 0.1 + gap) / per)), rows = min(pipes, fit), cols = ceil(pipes / fit);
f@per = per; i@fit = fit; i@rows = rows;
f@base = max(0.08, 0.3 * rail_height - (rows * per - gap) / 2);
f@d0 = 0.024 + 0.03 + r;
f@reach = pipes > 0 ? @d0 + (cols - 1) * per + r : 0.1;

// the bend radius of a corner: outside a left turn the pipe is farther out, inside a right turn closer in
const D = detail(0, 'd0') + floor(iteration / detail(0, 'fit')) * detail(0, 'per');
f@bend = @turn > 0 ? corner_radius + D : @turn < 0 ? max(corner_radius - D, 2 * pipe_radius) : 0;
